using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "UrchiriunsCustomAnimationData", menuName = "Data/Animation/UrchiriunsCustomAnimationData")]
public class UrchiriunsCustomAnimationData : CustomAnimationData
{
	public override void OnReceiveCorruption(SpriteControl spriteControl, CorruptionStats corruptionStats, AnimationData animationData)
	{
		float corruptionPercentage = corruptionStats.GetCorruptionPercentage();
		if (corruptionPercentage >= 0.33f)
		{
			if (corruptionPercentage <= 0.66f)
			{
				spriteControl.PlayAnimation(AnimationType.IdleHalfHP, AnimationChangeType.StayInTheNewAnimationLooping);
			}
			else
			{
				spriteControl.PlayAnimation(AnimationType.Idle, AnimationChangeType.StayInTheNewAnimationLooping);
			}
		}
	}

	public override bool OnReceivePurify(SpriteControl spriteControl, CorruptionStats corruptionStats, AnimationData animationData)
	{
		float corruptionPercentage = corruptionStats.GetCorruptionPercentage();
		if (corruptionPercentage <= 0.66f)
		{
			if (corruptionPercentage >= 0.33f)
			{
				spriteControl.PlayAnimation(AnimationType.IdleHalfHP, AnimationChangeType.StayInTheNewAnimationLooping);
			}
			else
			{
				spriteControl.PlayAnimation(AnimationType.IdleAlmostDead, AnimationChangeType.StayInTheNewAnimationLooping);
			}
			return true;
		}
		return false;
	}

	public override void OnActivateDice(GameObject source)
	{
	}
}
